1	// Shared contracts for every Roster module. Shapes follow docs/DESIGN.md §"Data model".
2	// Change minimally, and say so in your PR.
3	
4	/** Evidence level printed next to every claim: A observational, B controlled replay, C forward. */
5	export type EvidenceLevel = "A" | "B" | "C";
6	export const EVIDENCE_LEVELS: readonly EvidenceLevel[] = ["A", "B", "C"] as const;
7	
8	/** Failure taxonomy (DESIGN.md §"Grade"). */
9	export enum FailureCode {
10	  /** edited tests */
11	  F1 = "F1",
12	  /** never ran tests */
13	  F2 = "F2",
14	  /** suite regression */
15	  F3 = "F3",
16	  /** stopped early */
17	  F4 = "F4",
18	  /** loop, timeout or turn cap */
19	  F5 = "F5",
20	  /** environment or setup error; the task is excluded and resampled */
21	  F6 = "F6",
22	  /** off-scope edits */
23	  F7 = "F7",
24	}
25	
26	/** Where a session row came from. */
27	export type SessionSource = "branch" | "git-refs";
28	
29	/** One agent session, aggregated over all checkpoints it appears in. Table `sessions`. */
30	export interface Session {
31	  id: string;
32	  repo: string;
33	  checkpoint_id: string;
34	  harness: string;
35	  /** Resolved model, or "unknown" when neither metadata nor transcript records it. */
36	  model: string;
37	  /** sha256 of the normalised rules file; null when unknown, never a guess. */
38	  rules_hash: string | null;
39	  setup_id: string | null;
40	  tokens_in: number;
41	  tokens_out: number;
42	  cache_read: number;
43	  cache_write: number;
44	  /** null when the model's price is unknown. */
45	  cost_usd: number | null;
46	  n_user_prompts: number;
47	  first_prompt: string;
48	  /** null when no commit carries this session's checkpoint trailer. */
49	  commit_sha: string | null;
50	  started_at: string;
51	  ended_at: string;
52	  files: string[];
53	  entire_url: string | null;
54	  source: SessionSource;
55	}
