151	/** One pre-registered forward task run through both setups. Table `forward_pairs`. */
152	export interface ForwardPair {
153	  task_id: string;
154	  setup_old: string;
155	  setup_new: string;
156	  pass_old: boolean;
157	  pass_new: boolean;
158	  cost_old: number | null;
159	  cost_new: number | null;
160	  /** Which setup's change was merged, if any. */
161	  merged: "old" | "new" | null;
162	  /** Blind label assignment, e.g. { X: "old", Y: "new" }. */
163	  blind_labels: Record<string, "old" | "new">;
164	  seed: number;
165	  /** Per-step timings in milliseconds. */
166	  agent_old_ms?: number | null;
167	  agent_new_ms?: number | null;
168	  grade_ms?: number | null;
169	  /** Each side's full suite and scope guard; a suite is null when it did not run (only merge candidates run it) or on rows recorded before it was kept. */
170	  suite_pass_old?: boolean | null;
171	  suite_pass_new?: boolean | null;
172	  scope_ok_old?: boolean | null;
173	  scope_ok_new?: boolean | null;
174	  /** Why `merged` is what it is. The suite_scope* reasons are amendment 8's build-only policy for both-fail pairs. */
175	  merged_reason?:
176	    | "pass_beats_fail"
177	    | "judge"
178	    | "random_tie"
179	    | "suite_scope"
180	    | "suite_scope_judge"
181	    | "suite_scope_random_tie"
182	    | "both_failed"
183	    | "merge_failed"
184	    | null;
185	  /** Exploratory secondary outcome (amendment 8), never H1: the blind judge's preference among sides whose suite and scope pass. */
186	  secondary?: "old" | "new" | "tie" | "none" | null;
187	}
