1	// Deterministic promotion gate (DESIGN.md §"Gate"). Pure code: the coordinator can't override it.
2	//
3	// promote(candidate) iff, on the replay set (incumbent replayed as the control):
4	//   hidden_pass(candidate) ≥ hidden_pass(incumbent)
5	//   ∧ regressions == 0          # incumbent passed, candidate failed, after reruns
6	//   ∧ scope_violations == 0
7	//   ∧ cost(candidate) ≤ budget
8	// ties → cheaper wins; still tied → keep incumbent; a tie at zero hidden passes never promotes
9	// no_signal: the incumbent passes none of its ≥ NO_SIGNAL_MIN_TASKS tasks with hidden tests, so the measure
10	//   can't rank setups and nothing is promoted.
11	//
12	// Conventions:
13	// - Results are Replay rows; several rows for one task are reruns (`attempt`).
14	// - Attempts carrying F6 (environment error) are excluded. A task with no usable attempt on
15	//   either side is excluded from the comparison (it is resampled upstream).
16	// - A side passes a task when a strict majority of its usable attempts have hidden_pass === true.
17	//   A 1–1 split is not a majority, so it counts as not passing.
18	// - A task the incumbent has but the candidate lacks counts as a candidate failure.
19	// - cost(setup) = sum over compared tasks of the mean cost of that task's usable attempts, so
20	//   reruns don't penalise a setup. Any unknown (null) cost makes the cost unknown.
21	
22	import { FailureCode } from "../types.ts";
23	import type { GateVerdict, Replay } from "../types.ts";
24	
25	/** Max attempts per task and side (DESIGN.md §"Grade" step 6). */
26	export const MAX_ATTEMPTS = 3;
27	/** Fewest tasks with hidden tests before an incumbent with zero passes counts as no signal. */
28	export const NO_SIGNAL_MIN_TASKS = 3;
29	export const NO_SIGNAL_REASON = "the incumbent fails its own tasks: the replay measure has no signal";
30	
31	export type GateResults = Pick<
32	  Replay,
33	  "task_session_id" | "attempt" | "hidden_pass" | "scope_ok" | "cost_usd" | "failure_codes"
34	>[];
35	
36	export interface GateOptions {
37	  /** Cost cap for the candidate, in USD. */
38	  budget: number;
39	}
40	
41	/** How a hidden-pass tie was resolved: no tie, candidate cheaper, or kept incumbent. */
42	export type GateTie = "none" | "cheaper" | "incumbent";
43	
44	export interface GateResult {
45	  verdict: GateVerdict;
46	  reasons: string[];
47	  /** Task ids the incumbent passed and the candidate failed, after reruns. */
48	  regressions: string[];
49	  ties: GateTie;
50	  hidden_pass: { incumbent: number; candidate: number };
51	  /** Task ids where any usable candidate attempt had scope_ok === false. */
52	  scope_violations: string[];
53	  cost: { incumbent: number | null; candidate: number | null };
54	  /** Task ids excluded because one side had no usable attempt (all F6). */
55	  excluded: string[];
56	}
57	
58	interface Tally {
59	  attempts: number;
60	  passes: number;
61	  scopeViolation: boolean;
62	  /** Mean usable-attempt cost; null when any cost is unknown. */
63	  cost: number | null;
64	  /** The task has hidden tests: some usable attempt reports hidden_pass. Judge-only tasks report null. */
65	  tests: boolean;
66	}
67	
68	function usable(r: GateResults[number]): boolean {
69	  return !r.failure_codes.includes(FailureCode.F6);
70	}
71	
72	function tally(results: GateResults): Map<string, Tally> {
73	  const groups = new Map<string, GateResults>();
74	  for (const r of results) {
75	    if (!usable(r)) {
76	      if (!groups.has(r.task_session_id)) groups.set(r.task_session_id, []);
77	      continue;
78	    }
79	    const g = groups.get(r.task_session_id);
80	    if (g) g.push(r);
81	    else groups.set(r.task_session_id, [r]);
82	  }
83	  const out = new Map<string, Tally>();
84	  for (const [task, rs] of groups) {
85	    let sum = 0;
86	    let known = true;
87	    for (const r of rs) {
88	      if (r.cost_usd === null) known = false;
89	      else sum += r.cost_usd;
90	    }
91	    out.set(task, {
92	      attempts: rs.length,
93	      passes: rs.filter((r) => r.hidden_pass === true).length,
94	      scopeViolation: rs.some((r) => r.scope_ok === false),
95	      cost: known && rs.length > 0 ? sum / rs.length : null,
96	      tests: rs.some((r) => r.hidden_pass !== null),
97	    });
98	  }
99	  return out;
100	}
101	
102	function passes(t: Tally | undefined): boolean {
103	  return t !== undefined && t.passes * 2 > t.attempts;
104	}
105	
106	/** Majority is settled once no further attempt (up to MAX_ATTEMPTS) could flip it. */
107	function settled(t: Tally | undefined): boolean {
108	  if (!t || t.attempts === 0) return false; // missing: needs a first attempt
109	  const remaining = Math.max(0, MAX_ATTEMPTS - t.attempts);
110	  const fails = t.attempts - t.passes;
111	  return remaining === 0 || t.passes > fails + remaining || fails >= t.passes + remaining;
112	}
113	
114	export interface Discordant {
115	  task_session_id: string;
116	  /** Which sides need another attempt. */
117	  rerun: ("incumbent" | "candidate")[];
118	}
119	
120	/**
121	 * Tasks where the two setups split and at least one side's majority is not yet settled within
122	 * k = MAX_ATTEMPTS. Run one more attempt on each listed side, then call again until empty.
123	 */
124	export function discordant(incumbent: GateResults, candidate: GateResults): Discordant[] {
125	  const inc = tally(incumbent);
126	  const cand = tally(candidate);
127	  const tasks = [...new Set([...inc.keys(), ...cand.keys()])].sort();
128	  const out: Discordant[] = [];
129	  for (const task of tasks) {
130	    const i = inc.get(task);
131	    const c = cand.get(task);
132	    // All-F6 on either side: the task is excluded and resampled, not rerun.
133	    if (i?.attempts === 0 || c?.attempts === 0) continue;
134	    if (passes(i) === passes(c)) continue;
135	    const rerun: Discordant["rerun"] = [];
136	    if (!settled(i)) rerun.push("incumbent");
137	    if (!settled(c)) rerun.push("candidate");
138	    if (rerun.length > 0) out.push({ task_session_id: task, rerun });
139	  }
140	  return out;
141	}
142	
143	function totalCost(t: Map<string, Tally>, tasks: string[]): number | null {
144	  let sum = 0;
145	  for (const task of tasks) {
146	    const c = t.get(task)?.cost;
147	    if (c === null || c === undefined) return null;
148	    sum += c;
149	  }
150	  return sum;
151	}
152	
153	function fmt(n: number | null): string {
154	  return n === null ? "unknown" : `$${n.toFixed(4)}`;
155	}
156	
157	export function gate(incumbentResults: GateResults, candidateResults: GateResults, opts: GateOptions): GateResult {
158	  const inc = tally(incumbentResults);
159	  const cand = tally(candidateResults);
160	
161	  const excluded: string[] = [];
162	  const tasks: string[] = [];
163	  for (const task of [...new Set([...inc.keys(), ...cand.keys()])].sort()) {
164	    const i = inc.get(task);
165	    const c = cand.get(task);
166	    const allF6 = (t: Tally | undefined) => t !== undefined && t.attempts === 0;
167	    if (allF6(i) || allF6(c)) excluded.push(task);
168	    // Tasks only the candidate ran are not part of the incumbent's replay set.
169	    else if (i) tasks.push(task);
170	  }
171	
172	  const hidden = {
173	    incumbent: tasks.filter((t) => passes(inc.get(t))).length,
174	    candidate: tasks.filter((t) => passes(cand.get(t))).length,
175	  };
176	  const regressions = tasks.filter((t) => passes(inc.get(t)) && !passes(cand.get(t)));
177	  const scope_violations = tasks.filter((t) => cand.get(t)?.scopeViolation === true);
178	  const missing = tasks.filter((t) => !cand.has(t));
179	  const cost = { incumbent: totalCost(inc, tasks), candidate: missing.length ? null : totalCost(cand, tasks) };
180	
181	  const reasons: string[] = [];
182	  if (tasks.length === 0) reasons.push("empty replay set: no comparable tasks");
183	  if (hidden.candidate < hidden.incumbent)
184	    reasons.push(`hidden_pass ${hidden.candidate} < incumbent ${hidden.incumbent}`);
185	  if (regressions.length > 0) reasons.push(`${regressions.length} regression(s) after reruns: ${regressions.join(", ")}`);
186	  if (scope_violations.length > 0)
187	    reasons.push(`${scope_violations.length} scope violation(s): ${scope_violations.join(", ")}`);
188	  if (missing.length > 0) reasons.push(`candidate missing results for: ${missing.join(", ")}`);
189	  if (cost.candidate === null) reasons.push("candidate cost unknown; cannot verify budget");
190	  else if (cost.candidate > opts.budget) reasons.push(`cost ${fmt(cost.candidate)} > budget ${fmt(opts.budget)}`);
191	
192	  // The incumbent passing none of its tasks with hidden tests says the measure is broken, not that setups are equal.
193	  const testTasks = tasks.filter((t) => inc.get(t)?.tests === true);
194	  if (testTasks.length >= NO_SIGNAL_MIN_TASKS && testTasks.every((t) => !passes(inc.get(t)))) {
195	    reasons.unshift(NO_SIGNAL_REASON);
196	    return { verdict: "no_signal", reasons, regressions, ties: "none", hidden_pass: hidden, scope_violations, cost, excluded };
197	  }
198	
199	  let ties: GateTie = "none";
200	  if (reasons.length === 0 && hidden.candidate === hidden.incumbent) {
201	    // A 0–0 tie carries no quality signal: cost alone never promotes.
202	    if (hidden.candidate === 0) {
203	      ties = "incumbent";
204	      reasons.push("tie at 0 hidden passes: no quality signal, keep incumbent");
205	      return { verdict: "reject", reasons, regressions, ties, hidden_pass: hidden, scope_violations, cost, excluded };
206	    }
207	    // Rules passed with equal hidden_pass: candidate must be strictly cheaper.
208	    if (cost.incumbent !== null && cost.candidate !== null && cost.candidate < cost.incumbent) {
209	      ties = "cheaper";
210	      reasons.push(`tie on hidden_pass ${hidden.candidate}; candidate cheaper ${fmt(cost.candidate)} < ${fmt(cost.incumbent)}`);
211	      return { verdict: "promote", reasons, regressions, ties, hidden_pass: hidden, scope_violations, cost, excluded };
212	    }
213	    ties = "incumbent";
214	    reasons.push(
215	      `tie on hidden_pass ${hidden.candidate}; candidate not cheaper (${fmt(cost.candidate)} vs ${fmt(cost.incumbent)}), keep incumbent`,
216	    );
217	    return { verdict: "reject", reasons, regressions, ties, hidden_pass: hidden, scope_violations, cost, excluded };
218	  }
219	
220	  if (reasons.length > 0)
221	    return { verdict: "reject", reasons, regressions, ties, hidden_pass: hidden, scope_violations, cost, excluded };
222	  reasons.push(`hidden_pass ${hidden.candidate} > incumbent ${hidden.incumbent}, 0 regressions, within budget`);
223	  return { verdict: "promote", reasons, regressions, ties, hidden_pass: hidden, scope_violations, cost, excluded };
224	}
