1	#!/usr/bin/env bun
2	// Roster's command line. Each command lives in src/cli/<cmd>.ts and exports a Command; register it in COMMANDS below.
3	// See docs/DESIGN.md §"CLI".
4	import { acceptanceCommand } from "./cli/acceptance.ts";
5	import { forwardCommand } from "./cli/forward.ts";
6	import { reviewCommand } from "./cli/review.ts";
7	import { runCommand } from "./cli/run.ts";
8	
9	export interface Command {
10	  name: string;
11	  summary: string;
12	  usage: string;
13	  /** Runs the command with the arguments after its name. Resolves to the process exit code. */
14	  run: (args: string[]) => Promise<number>;
15	}
16	
17	export const COMMANDS: readonly Command[] = [reviewCommand, runCommand, forwardCommand, acceptanceCommand];
18	
19	function printUsage(out: (s: string) => void): void {
20	  out("usage: roster <command> [args]\n");
21	  out("commands:");
22	  for (const c of COMMANDS) out(`  ${c.name.padEnd(10)} ${c.summary}`);
23	}
24	
25	/** Dispatches argv (without the runtime and script path) to a command. Resolves to the exit code. */
26	export async function main(argv: string[]): Promise<number> {
27	  const [name, ...rest] = argv;
28	  if (name === undefined) {
29	    printUsage((s) => console.error(s));
30	    return 2;
31	  }
32	  if (name === "--help" || name === "-h" || name === "help") {
33	    printUsage((s) => console.log(s));
34	    return 0;
35	  }
36	  const cmd = COMMANDS.find((c) => c.name === name);
37	  if (!cmd) {
38	    console.error(`roster: unknown command "${name}"\n`);
39	    printUsage((s) => console.error(s));
40	    return 2;
41	  }
42	  if (rest.includes("--help") || rest.includes("-h")) {
43	    console.log(cmd.usage);
44	    return 0;
45	  }
46	  try {
47	    return await cmd.run(rest);
48	  } catch (err) {
49	    console.error(`roster ${cmd.name}: ${err instanceof Error ? err.message : String(err)}`);
50	    return 1;
51	  }
52	}
53	
54	if (import.meta.main) {
55	  process.exitCode = await main(process.argv.slice(2));
56	}
