1	// `roster acceptance --backlog <file> --out experiments/acceptance/`: writes frozen acceptance tests for each
2	// backlog task (DESIGN.md §"Forward run"). Calls DeepSeek via src/llm.
3	import { readFileSync } from "node:fs";
4	import { join, resolve } from "node:path";
5	import type { Command } from "../cli.ts";
6	import { acceptanceModel, generateAcceptance } from "../forward/acceptance.ts";
7	import { deepseekClient } from "../llm/client.ts";
8	import { UsageError } from "./review.ts";
9	
10	export const DEFAULT_OUT = "experiments/acceptance/";
11	
12	const USAGE = `usage: roster acceptance --backlog <file> [--out <dir>]
13	
14	  --backlog <file>  the forward backlog (## Fxx: title blocks, each with an INTERFACE: line)
15	  --out <dir>       where <Fxx>/acceptance.test.ts and INDEX.json go (default ${DEFAULT_OUT})
16	
17	Existing acceptance files are frozen and never overwritten. Model: ROSTER_ACCEPTANCE_MODEL (default deepseek-v4-pro).`;
18	
19	export interface AcceptanceArgs {
20	  backlog: string;
21	  out: string;
22	}
23	
24	/** Parses the arguments after `acceptance`. Throws UsageError on anything it does not accept. */
25	export function parseAcceptanceArgs(args: string[]): AcceptanceArgs {
26	  let backlog: string | undefined;
27	  let out = DEFAULT_OUT;
28	  for (let i = 0; i < args.length; i++) {
29	    const a = args[i]!;
30	    const eq = a.indexOf("=");
31	    const name = eq === -1 ? a : a.slice(0, eq);
32	    const takeValue = (): string => {
33	      if (eq !== -1) return a.slice(eq + 1);
34	      const v = args[++i];
35	      if (v === undefined || v.startsWith("--")) throw new UsageError(`${name} needs a value`);
36	      return v;
37	    };
38	    if (name === "--backlog") backlog = takeValue();
39	    else if (name === "--out") out = takeValue();
40	    else throw new UsageError(`unexpected argument ${a}`);
41	  }
42	  if (backlog === undefined) throw new UsageError("missing --backlog");
43	  return { backlog, out };
44	}
45	
46	export const acceptanceCommand: Command = {
47	  name: "acceptance",
48	  summary: "write frozen acceptance tests for the forward backlog",
49	  usage: USAGE,
50	  async run(args) {
51	    let parsed: AcceptanceArgs;
52	    try {
53	      parsed = parseAcceptanceArgs(args);
54	    } catch (err) {
55	      if (!(err instanceof UsageError)) throw err;
56	      console.error(`roster acceptance: ${err.message}\n\n${USAGE}`);
57	      return 2;
58	    }
59	    const res = await generateAcceptance({
60	      backlog: readFileSync(parsed.backlog, "utf8"),
61	      outDir: resolve(parsed.out),
62	      client: deepseekClient(),
63	      model: acceptanceModel(),
64	      typesSource: readFileSync(join(import.meta.dir, "..", "types.ts"), "utf8"),
65	    });
66	    console.log(`written ${res.written.length}, frozen ${res.skipped.length}, failed ${res.failed.length}`);
67	    if (res.failed.length) console.error(`rejected twice (output implemented the interface): ${res.failed.join(", ")}`);
68	    return res.failed.length ? 1 : 0;
69	  },
70	};
