19	const mark = (pass: boolean): string => (pass ? '✓' : '✗');
20	
21	const cell = (text: string): string => text.replace(/\|/g, '\\|').replace(/\r?\n/g, ' ');
22	
23	const cost = (usd: number | null): string =>
24	  usd === null || !Number.isFinite(usd) ? 'n/a' : usd.toFixed(2);
25	
26	export function renderPrBody(input: PrBodyInput): string {
27	  const { repo, incumbent, promoted, tasks, rejected, evidenceLevel } = input;
28	  const n = tasks.length;
29	  const candidatePasses = tasks.filter((t) => t.candidatePass).length;
30	  const incumbentPasses = tasks.filter((t) => t.incumbentPass).length;
31	
32	  const lines: string[] = [];
33	
34	  lines.push('## Summary', '');
35	  lines.push(`Roster promotes setup \`${promoted}\` over incumbent \`${incumbent}\` in \`${repo}\`.`, '');
36	  lines.push(`Evidence level: ${evidenceLevel}`, '');
37	  lines.push(`${candidatePasses} of ${n} tasks passed (incumbent ${incumbentPasses} of ${n})`, '');
38	
39	  lines.push('## Evidence', '');
40	  lines.push('| Task | Incumbent | Promoted | Cost (USD) |');
41	  lines.push('| --- | --- | --- | --- |');
42	  for (const t of tasks) {
43	    lines.push(`| ${cell(t.id)} | ${mark(t.incumbentPass)} | ${mark(t.candidatePass)} | ${cost(t.costUsd)} |`);
44	  }
45	  lines.push('');
46	
47	  lines.push('## Rejected candidates', '');
48	  if (rejected.length === 0) {
49	    lines.push('None');
50	  } else {
51	    for (const r of rejected) {
52	      lines.push(`- \`${r.candidate}\``);
53	      if (r.reasons.length === 0) {
54	        lines.push('  - No reason recorded');
55	      } else {
56	        for (const reason of r.reasons) lines.push(`  - ${reason.replace(/\r?\n/g, ' ')}`);
57	      }
58	    }
59	  }
60	  lines.push('');
61	
62	  lines.push('## Links', '');
63	  const links: string[] = [];
64	  for (const t of tasks) {
65	    if (t.traceUrl) links.push(`- ${t.id}: [trace](${t.traceUrl})`);
66	    if (t.entireUrl) links.push(`- ${t.id}: [entire](${t.entireUrl})`);
67	  }
68	  if (links.length === 0) lines.push('None');
69	  else lines.push(...links);
70	  lines.push('');
71	
72	  return lines.join('\n');
73	}
