// `roster act` (DESIGN.md §"Act"): turn the last gate decision into a branch with the promoted setup, and — with
// --pr — a pull request.
//
//   roster act --gate <gate.json> [--pr] [--dry-run]
//
// The gate file is a GateDecision plus the two things the decision needs to act on: the promoted `setup` (a Setup
// row) and the candidate `rules` file's contents. Everything the command touches is injected, so the command is
// testable without a repo: readJson, writeFile, git, openPr and stdout.
//
// A decision that is not "promote" prints "nothing to act on" and returns 0 — DESIGN.md's "no better setup found"
// is a valid outcome, not an error. For a promote decision the command creates `roster/promote-<id>`, writes
// `setups/<id>.json` and the setup's rules file, and commits "roster: promote setup <id>". Any git step that
// exits non-zero stops the run and returns 1.
//
// --dry-run is a property of the act, not of the commit: it is passed through to openPr, whose own contract is
// "build the gh command but never run it". A dry run therefore still writes the local branch and commit — the
// irreversible, outward-facing step is the pull request.

import { openPr, type OpenPrOptions, type RunResult } from "../act/open-pr.ts";
import type { GateDecision, Setup } from "../types.ts";
import type { Command } from "../cli.ts";
import { UsageError } from "./review.ts";

/** The gate decision file `act` reads. */
export interface ActGateFile extends GateDecision {
  /** The setup the decision promotes. */
  setup?: Setup;
  /** Contents of the candidate rules file, written to `setup.rules_path`. */
  rules?: string;
}

export interface ActDeps {
  readJson(p: string): Promise<unknown>;
  writeFile(p: string, s: string): Promise<void>;
  git(args: string[]): Promise<{ code: number; stdout: string }>;
  openPr(o: unknown): Promise<{ opened: boolean; url?: string; reason?: string }>;
  stdout(s: string): void;
}

export interface ActArgs {
  gate: string;
  pr: boolean;
  dryRun: boolean;
}

const USAGE = `usage: roster act --gate <gate.json> [--pr] [--dry-run]

  --gate <file>  a gate decision json ({verdict, candidate, setup, rules}); only "promote" is acted on
  --pr           open a pull request for the new branch after committing it
  --dry-run      with --pr, build the gh command but do not run it

Creates roster/promote-<id>, writes setups/<id>.json and the setup's rules file, and commits
"roster: promote setup <id>". Unknown or missing --gate is a usage error (exit 2).`;

/** Parses the arguments after `act`. Throws UsageError on anything it does not accept. */
export function parseActArgs(args: string[]): ActArgs {
  let gate: string | undefined;
  let pr = false;
  let dryRun = false;
  for (let i = 0; i < args.length; i++) {
    const a = args[i]!;
    const eq = a.indexOf("=");
    const name = eq === -1 ? a : a.slice(0, eq);
    const takeValue = (): string => {
      if (eq !== -1) return a.slice(eq + 1);
      const v = args[++i];
      if (v === undefined || v.startsWith("--")) throw new UsageError(`${name} needs a value`);
      return v;
    };
    if (name === "--gate") gate = takeValue();
    else if (name === "--pr" && eq === -1) pr = true;
    else if (name === "--dry-run" && eq === -1) dryRun = true;
    else throw new UsageError(`unexpected argument ${a}`);
  }
  if (gate === undefined) throw new UsageError("missing --gate");
  return { gate, pr, dryRun };
}

function message(err: unknown): string {
  return err instanceof Error ? err.message : String(err);
}

/** The pull request body: what was promoted, why the gate allowed it, and the trace to the evidence. */
export function renderActBody(gate: ActGateFile, id: string): string {
  const lines = [
    `Promotes setup \`${id}\` (candidate \`${gate.candidate}\`, decision \`${gate.id}\`).`,
    "",
    "## Gate",
    "",
  ];
  for (const reason of gate.reasons ?? []) lines.push(`- ${reason.replace(/\r?\n/g, " ")}`);
  if ((gate.reasons ?? []).length === 0) lines.push("- No reason recorded");
  const links: string[] = [];
  if (gate.trace_url) links.push(`- [trace](${gate.trace_url})`);
  if (links.length > 0) lines.push("", "## Links", "", ...links);
  lines.push("");
  return lines.join("\n");
}

/**
 * `act` runs in the operator's own repo, so the explicit `--pr` invocation is the opt-in DESIGN.md §"Act"
 * requires; repos that never opted in are never acted on unless someone runs this command there themselves.
 */
export const actAllowRepo = (_ownerRepo: string): boolean => true;

/** Runs one git step; prints and returns 1 when it exits non-zero, else null. */
async function gitStep(deps: ActDeps, args: string[]): Promise<number | null> {
  const res = await deps.git(args);
  if (res.code === 0) return null;
  const detail = res.stdout.trim();
  deps.stdout(`roster act: git ${args.join(" ")} failed (exit ${res.code})${detail ? `: ${detail}` : ""}\n`);
  return 1;
}

/**
 * Turns `--gate`'s decision into a branch (+ PR). Returns the process exit code: 0 when there was nothing to act
 * on or the branch and commit landed, 1 when a git step failed or the gate file could not be read, 2 on a usage
 * error.
 */
export async function runActCommand(args: string[], deps: ActDeps): Promise<number> {
  let parsed: ActArgs;
  try {
    parsed = parseActArgs(args);
  } catch (err) {
    if (!(err instanceof UsageError)) throw err;
    deps.stdout(`roster act: ${err.message}\n\n${USAGE}\n`);
    return 2;
  }

  let gate: ActGateFile;
  try {
    gate = (await deps.readJson(parsed.gate)) as ActGateFile;
  } catch (err) {
    deps.stdout(`roster act: cannot read ${parsed.gate}: ${message(err)}\n`);
    return 1;
  }

  if (gate?.verdict !== "promote") {
    deps.stdout("nothing to act on\n");
    return 0;
  }

  const setup = gate.setup;
  const id = setup?.id ?? gate.candidate;
  if (setup === undefined || !id) {
    deps.stdout(`roster act: decision ${gate.id ?? "(no id)"} is a promote but carries no setup\n`);
    return 1;
  }

  const branch = `roster/promote-${id}`;
  const setupPath = `setups/${id}.json`;
  // The registry's Setup rows carry the rules path; the fallback keeps a decision usable when it does not.
  const rulesPath = setup.rules_path ?? `rules/${id}.md`;

  const checkout = await gitStep(deps, ["checkout", "-b", branch]);
  if (checkout !== null) return checkout;

  await deps.writeFile(setupPath, `${JSON.stringify(setup, null, 2)}\n`);
  await deps.writeFile(rulesPath, gate.rules ?? "");

  const add = await gitStep(deps, ["add", setupPath, rulesPath]);
  if (add !== null) return add;
  const commit = await gitStep(deps, ["commit", "-m", `roster: promote setup ${id}`]);
  if (commit !== null) return commit;

  deps.stdout(`committed ${id} to ${branch}\n`);

  if (parsed.pr) {
    const opts: OpenPrOptions = {
      repoPath: ".",
      branch,
      title: `roster: promote setup ${id}`,
      body: renderActBody(gate, id),
      dryRun: parsed.dryRun,
      allowRepo: actAllowRepo,
    };
    const res = await deps.openPr(opts);
    if (res.opened) deps.stdout(`opened pull request${res.url ? ` ${res.url}` : ""}\n`);
    else deps.stdout(`no pull request: ${res.reason ?? "unknown reason"}\n`);
  }

  return 0;
}

/** Spawns git in `cwd`; the CLI's default `git` dep. */
function spawnGit(cwd: string) {
  return async (args: string[]): Promise<{ code: number; stdout: string }> => {
    const proc = Bun.spawn(["git", ...args], { cwd, stdin: "ignore", stdout: "pipe", stderr: "pipe" });
    const [stdout, code] = await Promise.all([new Response(proc.stdout).text(), proc.exited]);
    return { code, stdout };
  };
}

/** The real dependencies: the working directory's files and git, and src/act/open-pr.ts. */
export function defaultActDeps(cwd = process.cwd()): ActDeps {
  return {
    readJson: async (p) => JSON.parse(await Bun.file(p).text()) as unknown,
    writeFile: async (p, s) => {
      await Bun.write(p, s);
    },
    git: spawnGit(cwd),
    openPr: async (o) => {
      const res = await openPr(o as OpenPrOptions);
      const { opened, url, reason } = res;
      return reason === undefined ? { opened, url } : { opened, url, reason };
    },
    stdout: (s) => {
      process.stdout.write(s);
    },
  };
}

/** Placeholder for the unused RunResult import marker; keeps the open-pr contract linked. */
export type { RunResult };

export const actCommand: Command = {
  name: "act",
  summary: "turn a promote gate decision into a branch and, with --pr, a pull request",
  usage: USAGE,
  run: (args) => runActCommand(args, defaultActDeps()),
};

