input.content:
// F14: `roster act` — a promote gate decision becomes a branch (+ PR). Companion to the frozen acceptance test
// (experiments/acceptance/F14/tests/acceptance/F14.test.ts); everything external is injected, so no repo is
// touched here.
import { describe, expect, test, mock } from "bun:test";
import {
  actAllowRepo,
  defaultActDeps,
  parseActArgs,
  renderActBody,
  runActCommand,
  type ActDeps,
  type ActGateFile,
} from "../src/cli/act.ts";

const setup = {
  id: "setup-1",
  harness: "claude-code",
  model: "deepseek-flash",
  rules_hash: "abc123",
  rules_path: "rules/setup-1.md",
  label: "candidate",
};

const promoteGate: ActGateFile = {
  id: "decision-1",
  plan_id: "plan-1",
  candidate: "setup-1",
  verdict: "promote",
  reasons: ["hidden_pass 6 > incumbent 4, 0 regressions, within budget"],
  trace_url: "https://neatlogs.example/trace/1",
  setup,
  rules: "candidate rules content",
};

/** Records every call so a case can assert on the exact argv. */
function createDeps(overrides: Partial<ActDeps> = {}) {
  const calls = {
    git: [] as string[][],
    written: [] as Array<[string, string]>,
    stdout: [] as string[],
    openPr: [] as unknown[],
  };
  const deps: ActDeps = {
    readJson: async () => promoteGate,
    writeFile: async (p, s) => {
      calls.written.push([p, s]);
    },
    git: async (args) => {
      calls.git.push(args);
      return { code: 0, stdout: "" };
    },
    openPr: async (o) => {
      calls.openPr.push(o);
      return { opened: true, url: "https://github.com/o/r/pull/7" };
    },
    stdout: (s) => {
      calls.stdout.push(s);
    },
    ...overrides,
  };
  return { deps, calls };
}

const printed = (calls: { stdout: string[] }) => calls.stdout.join("");

describe("parseActArgs", () => {
  test("accepts --gate, --pr and --dry-run in either value form", () => {
    expect(parseActArgs(["--gate", "g.json"])).toEqual({ gate: "g.json", pr: false, dryRun: false });
    expect(parseActArgs(["--gate=g.json", "--pr", "--dry-run"])).toEqual({ gate: "g.json", pr: true, dryRun: true });
  });

  test("rejects a missing --gate, a valueless --gate and unknown flags", () => {
    expect(() => parseActArgs([])).toThrow("missing --gate");
    expect(() => parseActArgs(["--gate", "--pr"])).toThrow("--gate needs a value");
    expect(() => parseActArgs(["--gate", "g.json", "--nope"])).toThrow("unexpected argument --nope");
  });
});

describe("runActCommand", () => {
  test("a decision that is not promote prints nothing to act on and touches nothing", async () => {
    for (const verdict of ["reject", "no_signal", undefined]) {
      const { deps, calls } = createDeps({ readJson: async () => ({ ...promoteGate, verdict }) });
      expect(await runActCommand(["--gate", "gate.json"], deps)).toBe(0);
      expect(printed(calls)).toContain("nothing to act on");
      expect(calls.written).toHaveLength(0);
      expect(calls.git).toHaveLength(0);
      expect(calls.openPr).toHaveLength(0);
    }
  });

  test("a promote writes the setup and rules, branches, adds and commits", async () => {
    const { deps, calls } = createDeps();
    expect(await runActCommand(["--gate", "gate.json"], deps)).toBe(0);

    expect(calls.written.map(([p]) => p)).toEqual(["setups/setup-1.json", "rules/setup-1.md"]);
    expect(JSON.parse(calls.written[0]![1])).toEqual(setup);
    expect(calls.written[1]![1]).toBe("candidate rules content");

    expect(calls.git).toEqual([
      ["checkout", "-b", "roster/promote-setup-1"],
      ["add", "setups/setup-1.json", "rules/setup-1.md"],
      ["commit", "-m", "roster: promote setup setup-1"],
    ]);
    expect(calls.openPr).toHaveLength(0);
    expect(printed(calls)).toContain("roster/promote-setup-1");
  });

  test("--pr opens a pull request for the branch; without it, never", async () => {
    const { deps, calls } = createDeps();
    expect(await runActCommand(["--gate", "gate.json", "--pr"], deps)).toBe(0);

    expect(calls.openPr).toHaveLength(1);
    const opts = calls.openPr[0] as Record<string, unknown>;
    expect(opts.branch).toBe("roster/promote-setup-1");
    expect(opts.title).toBe("roster: promote setup setup-1");
    expect(opts.dryRun).toBe(false);
    expect(String(opts.body)).toContain("setup-1");
    expect(printed(calls)).toContain("https://github.com/o/r/pull/7");
  });

  test("--pr --dry-run passes dryRun through and commits all the same", async () => {
    const { deps, calls } = createDeps();
    expect(await runActCommand(["--gate", "gate.json", "--pr", "--dry-run"], deps)).toBe(0);

    expect((calls.openPr[0] as Record<string, unknown>).dryRun).toBe(true);
    // DESIGN.md §"Act": the dry run is open-pr's ("build the command but never run gh"), so the local branch lands.
    expect(calls.git).toHaveLength(3);
    expect(printed(calls)).toContain("no pull request: dry run");
  });

  test("a failed git step stops the run and returns 1", async () => {
    const { deps, calls } = createDeps({ git: async () => ({ code: 128, stdout: "fatal: a branch named x exists" }) });
    expect(await runActCommand(["--gate", "gate.json"], deps)).toBe(1);
    expect(calls.git).toHaveLength(1);
    expect(calls.written).toHaveLength(0);
    expect(printed(calls)).toContain("git checkout -b roster/promote-setup-1 failed (exit 128)");
  });

  test("a commit that fails after the writes returns 1 and reports the step", async () => {
    const { deps, calls } = createDeps({
      git: async (args) => (args[0] === "commit" ? { code: 1, stdout: "nothing to commit" } : { code: 0, stdout: "" }),
    });
    expect(await runActCommand(["--gate", "gate.json"], deps)).toBe(1);
    expect(calls.git.map((a) => a[0])).toEqual(["checkout", "add", "commit"]);
    expect(calls.written).toHaveLength(2);
    expect(printed(calls)).toContain("git commit -m roster: promote setup setup-1 failed (exit 1)");
  });

  test("a pull request that does not open is reported but is not a git failure", async () => {
    const { deps, calls } = createDeps({ openPr: async () => ({ opened: false, reason: "not opted in" }) });
    expect(await runActCommand(["--gate", "gate.json", "--pr"], deps)).toBe(0);
    expect(printed(calls)).toContain("no pull request: not opted in");
  });

  test("an unreadable gate file returns 1", async () => {
    const { deps, calls } = createDeps({
      readJson: async () => {
        throw new Error("ENOENT: no such file");
      },
    });
    expect(await runActCommand(["--gate", "gone.json"], deps)).toBe(1);
    expect(printed(calls)).toContain("cannot read gone.json");
    expect(calls.git).toHaveLength(0);
  });

  test("a promote decision with no setup returns 1", async () => {
    const { deps, calls } = createDeps({ readJson: async () => ({ ...promoteGate, setup: undefined }) });
    expect(await runActCommand(["--gate", "gate.json"], deps)).toBe(1);
    expect(printed(calls)).toContain("carries no setup");
    expect(calls.git).toHaveLength(0);
  });

  test("a setup without a rules_path falls back to rules/<id>.md", async () => {
    const { deps, calls } = createDeps({
      readJson: async () => ({ ...promoteGate, setup: { ...setup, rules_path: null } }),
    });
    expect(await runActCommand(["--gate", "gate.json"], deps)).toBe(0);
    expect(calls.written.map(([p]) => p)).toEqual(["setups/setup-1.json", "rules/setup-1.md"]);
  });

  test("a usage error prints usage and returns 2", async () => {
    const { deps, calls } = createDeps();
    expect(await runActCommand([], deps)).toBe(2);
    expect(printed(calls)).toContain("missing --gate");
    expect(printed(calls)).toContain("usage: roster act");
  });

  test("the command calls the git dep it was handed, once per step", async () => {
    // The frozen acceptance test's last case overrides `git` and asserts on the un-overridden mock, which no
    // implementation can call: createDeps spreads the override into `deps` but returns the original mock. What
    // the case intends — the failing injected git is what act calls, and its failure is exit 1 — is this test.
    const git = mock(async (_args: string[]) => ({ code: 1, stdout: "fatal" }));
    const { deps } = createDeps({ git });
    expect(await runActCommand(["--gate", "gate.json"], deps)).toBe(1);
    expect(git).toHaveBeenCalledTimes(1);
  });
});

describe("renderActBody", () => {
  test("lists the gate's reasons and links the trace", () => {
    const body = renderActBody(promoteGate, "setup-1");
    expect(body).toContain("`setup-1`");
    expect(body).toContain("- hidden_pass 6 > incumbent 4, 0 regressions, within budget");
    expect(body).toContain("[trace](https://neatlogs.example/trace/1)");
  });

  test("says so when the decision carries no reason or trace", () => {
    const body = renderActBody({ ...promoteGate, reasons: [], trace_url: null }, "setup-1");
    expect(body).toContain("- No reason recorded");
    expect(body).not.toContain("[trace]");
  });
});

describe("actAllowRepo", () => {
  test("an explicit `act --pr` in the operator's own repo is the opt-in", () => {
    expect(actAllowRepo("owner/name")).toBe(true);
  });
});

describe("defaultActDeps", () => {
  test("reads json, writes files, runs git and prints", () => {
    const deps = defaultActDeps();
    for (const fn of [deps.readJson, deps.writeFile, deps.git, deps.openPr, deps.stdout]) {
      expect(typeof fn).toBe("function");
    }
  });
});

