/** Records every call so a case can assert on the exact argv, even when a case overrides the implementation. */
function createDeps(overrides: Partial<ActDeps> = {}) {
  const calls = {
    git: [] as string[][],
    written: [] as Array<[string, string]>,
    stdout: [] as string[],
    openPr: [] as unknown[],
  };
  const deps: ActDeps = {
    readJson: overrides.readJson ?? (async () => promoteGate),
    writeFile: async (p, s) => {
      calls.written.push([p, s]);
      await overrides.writeFile?.(p, s);
    },
    git: async (args) => {
      calls.git.push(args);
      return overrides.git ? await overrides.git(args) : { code: 0, stdout: "" };
    },
    openPr: async (o) => {
      calls.openPr.push(o);
      return overrides.openPr ? await overrides.openPr(o) : { opened: true, url: "https://github.com/o/r/pull/7" };
    },
    stdout: (s) => {
      calls.stdout.push(s);
      overrides.stdout?.(s);
    },
  };
  return { deps, calls };
}

